import { forwardRef, useId, useImperativeHandle, useMemo, useRef, type ComponentProps } from "react";
import { AbsoluteFill, Easing, Interactive, Sequence, interpolate, random, useCurrentFrame, useVideoConfig, type InteractiveBaseProps, type InteractiveTransformProps, type InteractivitySchema, type SequenceControls } from "remotion";

// Every timing in remocn is written in frames of a 30 fps timeline: a delay
// of 12, a rise over 20, a spring fed `fps`. Read straight from Remotion,
// those numbers mean something else in a 60 fps composition: a tween runs
// twice as fast, while a spring keeps its length, so a scene does not even
// speed up evenly.
//
// These two hooks stand in for Remotion's and answer on that 30 fps timeline
// whatever rate the composition runs at. At 60 fps the frame goes 0, 0.5, 1,
// 1.5: the scene lasts the same number of seconds and every frame in between
// is a new picture. At 30 fps they return exactly what Remotion does.
//
//   const frame = useSceneFrame();
//   const { fps, width } = useSceneConfig();
//
// What a component hands back to Remotion is still counted in the
// composition's own frames: `from` and `durationInFrames` of a `<Sequence>`,
// the length of a transition. `useCompositionFrames()` converts those.

/** The frame rate remocn timings are written in. */
const SCENE_FPS = 30;

/** `useCurrentFrame()` in 30 fps frames; fractional above 30 fps. */
function useSceneFrame(): number {
  const { fps } = useVideoConfig();
  return (useCurrentFrame() * SCENE_FPS) / fps;
}

/**
 * `useVideoConfig()` on the 30 fps timeline: `fps` is 30 and
 * `durationInFrames` counts 30 fps frames. Size and the rest are untouched.
 */
function useSceneConfig(): ReturnType<typeof useVideoConfig> {
  const config = useVideoConfig();
  return useMemo(
    () => ({
      ...config,
      fps: SCENE_FPS,
      durationInFrames: (config.durationInFrames * SCENE_FPS) / config.fps,
    }),
    [config],
  );
}

/**
 * Turns a count of 30 fps frames into the composition's own, for what
 * Remotion itself reads: `<Sequence from={frames(24)}>`. Whole frames only,
 * as Remotion requires.
 */
function useCompositionFrames(): (sceneFrames: number) => number {
  const { fps } = useVideoConfig();
  return useMemo(
    () => (sceneFrames: number) => Math.round((sceneFrames * fps) / SCENE_FPS),
    [fps],
  );
}

/**
 * The other way round: a count Remotion gives a component in the
 * composition's own frames, in 30 fps frames. A transition's presentation
 * gets its length that way (`presentationDurationInFrames`).
 */
function useSceneFrameCount(): (compositionFrames: number) => number {
  const { fps } = useVideoConfig();
  return useMemo(
    () => (compositionFrames: number) => (compositionFrames * SCENE_FPS) / fps,
    [fps],
  );
}

// A component's schedule, kept apart from its drawing: which elements the
// animation has (an entry, a word, a finale), when each starts and how long
// it runs. The schedule is a pure function of the props, so it can be read
// without rendering anything, and a `timing` prop can move, trim or stretch
// single elements without touching the code that draws them.
//
//   // timeline.ts, next to the component
//   export const titleTimeline = defineTimeline<TitleElementId, TitleProps>(
//     ({ words = WORDS }, { length }) =>
//       words.map((word, k) => ({
//         id: `word:${k}`,
//         lane: "Words",
//         label: word,
//         start: k * 8,
//         length: 8,
//         follows: k > 0 ? `word:${k - 1}` : undefined,
//         beats: { rise: 12 },
//       })),
//   );
//
//   // index.tsx
//   const tl = useTimeline(titleTimeline, props, length, timing);
//   const word = tl.get("word:0");
//   interpolate(t, [word.start, word.start + word.beat("rise")], [0, 1]);
//
// Every number is in frames of the 30 fps scene timeline, after `delay` and
// `speed`: those still apply to the whole animation, `timing` works inside it.
// Element ids are public API: a saved `timing` refers to them, so an id once
// shipped keeps its meaning.

/** One timed part of an animation, as its schedule lays it out. */
interface TimelineElement<Id extends string = string> {
  /** Stable name a `timing` override refers to: `entry:0`, `finale`. */
  id: Id;
  /** Row the element sits on in a timeline view. */
  lane: string;
  /** What the element shows, for people reading the timeline. */
  label: string;
  /** First frame of the element. */
  start: number;
  /** Frames until the next element of the lane takes over, or the end. */
  length: number;
  /**
   * The element this one comes after. When that element's end moves, this
   * one moves with it, keeping the gap between them.
   */
  follows?: Id;
  /**
   * Named frame counts inside the element, measured from its start: how long
   * a roll takes, when a second part begins. `stretch` scales them.
   */
  beats?: Record<string, number>;
}

/** A change to one element, made from outside the component. */
interface TimingOverride {
  /** New first frame. Wins over the shift from `follows`. */
  start?: number;
  /** New length, trimming or extending the element. Wins over `stretch`. */
  length?: number;
  /** Multiplies the length and every beat: 2 plays the element half as fast. */
  stretch?: number;
  /** Stops following: the element keeps its own start when the one before moves. */
  detach?: boolean;
}

/** Overrides by element id: the `timing` prop of a component. */
type Timing<Id extends string = string> = Partial<
  Record<Id, TimingOverride>
>;

/** A component's schedule: props and the scene length in, elements out. */
type Schedule<Id extends string, Props> = (
  props: Props,
  scene: { length: number },
) => TimelineElement<Id>[];

/** An element after `timing` has been applied. */
interface ResolvedElement<Id extends string = string>
  extends TimelineElement<Id> {
  /** `start + length`. */
  end: number;
  beats: Record<string, number>;
  /** A beat by name, stretched. Throws on a name the schedule didn't set. */
  beat(name: string): number;
  /**
   * 0 → 1 over the element, or over its first `beat` frames when a beat is
   * named. Clamped on both sides.
   */
  progress(frame: number, beat?: string): number;
}

interface ResolvedTimeline<Id extends string = string> {
  /** All elements, in the order the schedule returned them. */
  elements: ResolvedElement<Id>[];
  /** An element by id. Throws on an id the schedule didn't return. */
  get(id: Id): ResolvedElement<Id>;
  /** The elements of one lane, in order. */
  lane(name: string): ResolvedElement<Id>[];
}

/** Declares a schedule. Elements come back in time order. */
function defineTimeline<Id extends string, Props>(
  schedule: Schedule<Id, Props>,
): Schedule<Id, Props> {
  return schedule;
}

/** Applies `timing` to a schedule's elements and carries the `follows` chains. */
function resolve<Id extends string>(
  elements: TimelineElement<Id>[],
  timing: Timing<Id> = {},
): ResolvedTimeline<Id> {
  const byId = new Map<Id, TimelineElement<Id>>(elements.map((e) => [e.id, e]));
  const done = new Map<Id, ResolvedElement<Id>>();
  const visiting = new Set<Id>();

  const place = (element: TimelineElement<Id>): ResolvedElement<Id> => {
    const known = done.get(element.id);
    if (known) return known;
    if (visiting.has(element.id)) {
      throw new Error(`timeline: "${element.id}" follows itself`);
    }
    visiting.add(element.id);

    const override: TimingOverride = timing[element.id] ?? {};
    const stretch = override.stretch ?? 1;
    const beats: Record<string, number> = {};
    for (const [name, frames] of Object.entries(element.beats ?? {})) {
      beats[name] = frames * stretch;
    }

    let start = element.start;
    const leader = element.follows ? byId.get(element.follows) : undefined;
    if (leader && !override.detach) {
      // The leader's end moved by this much; this element moves as far.
      start += place(leader).end - (leader.start + leader.length);
    }
    if (override.start !== undefined) start = override.start;
    const length = override.length ?? element.length * stretch;

    const beat = (name: string) => {
      const frames = beats[name];
      if (frames === undefined) {
        throw new Error(`timeline: "${element.id}" has no beat "${name}"`);
      }
      return frames;
    };
    const resolved: ResolvedElement<Id> = {
      ...element,
      start,
      length,
      end: start + length,
      beats,
      beat,
      progress: (frame, name) => {
        const span = name === undefined ? length : beat(name);
        if (span <= 0) return frame >= start ? 1 : 0;
        return Math.min(1, Math.max(0, (frame - start) / span));
      },
    };
    visiting.delete(element.id);
    done.set(element.id, resolved);
    return resolved;
  };

  const all = elements.map(place);
  return {
    elements: all,
    get: (id) => {
      const element = done.get(id);
      if (!element) throw new Error(`timeline: no element "${id}"`);
      return element;
    },
    lane: (name) => all.filter((e) => e.lane === name),
  };
}

/**
 * The component side: runs the schedule and applies `timing`, once per
 * change of its inputs. `length` is the scene length the schedule fits into,
 * in the same frames the component counts.
 */
function useTimeline<Id extends string, Props>(
  schedule: Schedule<Id, Props>,
  props: Props,
  length: number,
  timing?: Timing<Id>,
): ResolvedTimeline<Id> {
  return useMemo(
    () => resolve(schedule(props, { length }), timing),
    [schedule, props, length, timing],
  );
}

// The intro of the synthwave loop: the sun rises over the horizon while the
// back range and then the front range slide in from the side. The grid,
// stars and sun stripes run on forever and are not elements. Frames on the
// 30 fps scene timeline, after `speed`. The ids are public: a saved `timing`
// prop refers to them.

type SynthwaveElementId = "sun" | "back" | "front";

const synthwaveTimeline = defineTimeline<SynthwaveElementId, object>(
  () => [
    { id: "sun", lane: "Sun", label: "sun rises", start: 0, length: 40 },
    {
      id: "back",
      lane: "Mountains",
      label: "back range",
      start: 4,
      length: 30,
    },
    {
      id: "front",
      lane: "Mountains",
      label: "front range",
      start: 8,
      length: 30,
    },
  ],
);

type SynthwaveColors = {
  skyTop: string;
  skyHorizon: string;
  sunTop: string;
  sunBottom: string;
  grid: string;
  floor: string;
  mountainsBack: string;
  mountainsFront: string;
};

type SynthwaveProps = {
  colors?: Partial<SynthwaveColors>;
  /** Grid line color. Overrides `colors.grid` when set. */
  grid?: string;
  /** Top of the sun gradient. Overrides `colors.sunTop` when set. */
  sunTop?: string;
  /** Bottom of the sun gradient. Overrides `colors.sunBottom` when set. */
  sunBottom?: string;
  /** Sky glow at the horizon. Overrides `colors.skyHorizon` when set. */
  skyHorizon?: string;
  /** Grid rows that pass the viewer per second. */
  gridSpeed?: number;
  /** Horizon height as a fraction of the frame. */
  horizon?: number;
  /** Scroll the sun stripes downward. */
  sunStripes?: boolean;
  speed?: number;
  /**
   * Moves, trims or stretches the sun rise and the two mountain ranges, by
   * the ids in `./timeline`. Frames on the scene timeline, after `speed`.
   */
  timing?: Timing<SynthwaveElementId>;
};

const synthwaveDefaults = {
  colors: {
    skyTop: "#08080B",
    skyHorizon: "#3B0C10",
    sunTop: "#FFC46B",
    sunBottom: "#E5322D",
    grid: "#E5322D",
    floor: "#0A0A0C",
    mountainsBack: "#2A0A0E",
    mountainsFront: "#111111",
  } as SynthwaveColors,
  gridSpeed: 2,
  horizon: 0.6,
  sunStripes: true,
  speed: 1,
};

/** Frames until the sun and mountains are in place; the grid loops forever. */
const synthwaveLength = 40;

const clamp = {
  extrapolateLeft: "clamp" as const,
  extrapolateRight: "clamp" as const,
};

function ridge(
  seed: string,
  width: number,
  base: number,
  peak: number,
  count: number,
) {
  // Spans well past both edges so the slide never exposes an end.
  const points: string[] = [`${-0.4 * width},${base}`];
  for (let i = 0; i <= count; i++) {
    const x = -0.4 * width + (i / count) * 1.8 * width;
    const center = Math.min(1, Math.abs(x - width / 2) / (0.45 * width));
    const valley = 0.18 + 0.82 * center * center;
    const jag = 0.45 + 0.55 * random(`${seed}-${i}`);
    const y = base - peak * valley * (i % 2 === 0 ? jag : jag * 0.45);
    points.push(`${x},${y}`);
  }
  points.push(`${1.4 * width},${base}`);
  return points.join(" ");
}

function SynthwaveBase(props: SynthwaveProps) {
  const {
    colors,
    grid,
    sunTop,
    sunBottom,
    skyHorizon,
    gridSpeed = synthwaveDefaults.gridSpeed,
    horizon = synthwaveDefaults.horizon,
    sunStripes = synthwaveDefaults.sunStripes,
    speed = synthwaveDefaults.speed,
    timing,
  } = props;
  const frame = useSceneFrame();
  const { width: W, height: H, fps, durationInFrames } = useSceneConfig();
  const tl = useTimeline(
    synthwaveTimeline,
    props,
    durationInFrames * speed,
    timing,
  );
  const sun = tl.get("sun");
  const backRange = tl.get("back");
  const frontRange = tl.get("front");
  const id = useId().replace(/[^a-zA-Z0-9_-]/g, "");
  const merged = { ...synthwaveDefaults.colors, ...colors };
  const c: SynthwaveColors = {
    ...merged,
    grid: grid ?? merged.grid,
    sunTop: sunTop ?? merged.sunTop,
    sunBottom: sunBottom ?? merged.sunBottom,
    skyHorizon: skyHorizon ?? merged.skyHorizon,
  };
  const u = Math.min(W, H) / 720;
  const t = (frame / fps) * 30 * speed;
  const cx = W / 2;
  const yh = horizon * H;
  const floorDepth = H - yh;

  // Floor: screen y = yh + floorDepth / z, so z = 1 is the bottom edge.
  const rowGap = 0.5;
  const phase = ((((t / 30) * gridSpeed) % 1) + 1) % 1;
  const rows: { y: number; o: number }[] = [];
  for (let k = 0; k < 70; k++) {
    const z = 0.7 + (k + 1 - phase) * rowGap;
    const y = yh + floorDepth / z;
    if (y > H + 4 * u) continue;
    rows.push({ y, o: interpolate(z, [1, 14, 30], [1, 0.35, 0], clamp) });
  }
  const columns = Array.from({ length: 23 }, (_, i) => i - 11);
  const colSpread = W * 0.16;
  const nearZ = 0.35;

  const rise = interpolate(t, [sun.start, sun.end], [0, 1], {
    ...clamp,
    easing: Easing.out(Easing.cubic),
  });
  const R = 0.27 * H;
  const sunY = interpolate(rise, [0, 1], [yh + R * 1.05, yh - R * 0.42]);
  const stripePhase = sunStripes ? (((t / 36) % 1) + 1) % 1 : 0;
  const stripes = Array.from({ length: 7 }, (_, i) => {
    const p = (i + stripePhase) / 7;
    const y = sunY + R * (-0.05 + p * 1.05);
    const h = R * (0.012 + 0.09 * p);
    return { y: y - h / 2, h };
  });

  const back = useMemo(
    () => ridge("synthwave-back", W, yh, 0.26 * H, 27),
    [W, H, yh],
  );
  const front = useMemo(
    () => ridge("synthwave-front", W, yh, 0.15 * H, 39),
    [W, H, yh],
  );
  // Ranges slide in sideways while rising from behind the horizon.
  const slideBack = interpolate(t, [backRange.start, backRange.end], [1, 0], {
    ...clamp,
    easing: Easing.out(Easing.cubic),
  });
  const slideFront = interpolate(
    t,
    [frontRange.start, frontRange.end],
    [1, 0],
    {
      ...clamp,
      easing: Easing.out(Easing.cubic),
    },
  );
  const stars = Array.from({ length: 70 }, (_, i) => ({
    x: random(`synthwave-sx-${i}`) * W,
    y: random(`synthwave-sy-${i}`) * yh * 0.8,
    r: (0.6 + random(`synthwave-sr-${i}`) * 1.4) * u,
    o:
      0.25 +
      0.5 * (0.5 + 0.5 * Math.sin(t * 0.15 + random(`synthwave-sp-${i}`) * 9)),
  }));

  return (
    <AbsoluteFill style={{ backgroundColor: c.floor, overflow: "hidden" }}>
      <svg width={W} height={H} viewBox={`0 0 ${W} ${H}`} aria-hidden>
        <defs>
          <linearGradient id={`${id}-sky`} x1="0" y1="0" x2="0" y2="1">
            <stop offset="0" stopColor={c.skyTop} />
            <stop offset="0.55" stopColor={c.skyTop} />
            <stop offset="1" stopColor={c.skyHorizon} />
          </linearGradient>
          <linearGradient id={`${id}-sun`} x1="0" y1="0" x2="0" y2="1">
            <stop offset="0.1" stopColor={c.sunTop} />
            <stop offset="0.85" stopColor={c.sunBottom} />
          </linearGradient>
          <linearGradient id={`${id}-floor`} x1="0" y1="0" x2="0" y2="1">
            <stop offset="0" stopColor={c.skyHorizon} />
            <stop offset="0.25" stopColor={c.floor} />
          </linearGradient>
          <mask id={`${id}-stripes`}>
            <rect width={W} height={H} fill="#fff" />
            {stripes.map((s, i) => (
              <rect key={i} x={0} y={s.y} width={W} height={s.h} fill="#000" />
            ))}
          </mask>
          <clipPath id={`${id}-above`}>
            <rect width={W} height={yh} />
          </clipPath>
          <filter
            id={`${id}-glow`}
            x="-20%"
            y="-20%"
            width="140%"
            height="140%"
          >
            <feGaussianBlur stdDeviation={4 * u} result="blur" />
            <feMerge>
              <feMergeNode in="blur" />
              <feMergeNode in="blur" />
              <feMergeNode in="SourceGraphic" />
            </feMerge>
          </filter>
          <filter
            id={`${id}-haze`}
            x="-50%"
            y="-50%"
            width="200%"
            height="200%"
          >
            <feGaussianBlur stdDeviation={30 * u} />
          </filter>
        </defs>

        <rect width={W} height={yh} fill={`url(#${id}-sky)`} />
        <g fill="#FFFFFF">
          {stars.map((s, i) => (
            <circle key={i} cx={s.x} cy={s.y} r={s.r} opacity={s.o} />
          ))}
        </g>

        <g clipPath={`url(#${id}-above)`}>
          <circle
            cx={cx}
            cy={sunY}
            r={R * 1.15}
            fill={c.sunBottom}
            opacity={0.45}
            filter={`url(#${id}-haze)`}
          />
          <circle
            cx={cx}
            cy={sunY}
            r={R}
            fill={`url(#${id}-sun)`}
            mask={`url(#${id}-stripes)`}
          />
          <polygon
            points={back}
            fill={c.mountainsBack}
            transform={`translate(${-0.25 * W * slideBack} ${0.3 * H * slideBack})`}
          />
          <g
            transform={`translate(${0.25 * W * slideFront} ${0.2 * H * slideFront})`}
          >
            <polygon points={front} fill={c.mountainsFront} />
            <polyline
              points={front}
              fill="none"
              stroke={c.grid}
              strokeWidth={1.5 * u}
              strokeOpacity={0.55}
              strokeLinejoin="round"
            />
          </g>
        </g>

        <rect y={yh} width={W} height={H - yh} fill={`url(#${id}-floor)`} />
        <g
          stroke={c.grid}
          strokeWidth={2.2 * u}
          filter={`url(#${id}-glow)`}
          fill="none"
        >
          {columns.map((j) => (
            <line
              key={j}
              x1={cx}
              y1={yh}
              x2={cx + (j * colSpread) / nearZ}
              y2={yh + floorDepth / nearZ}
            />
          ))}
          {rows.map((row, i) => (
            <line
              key={i}
              x1={0}
              y1={row.y}
              x2={W}
              y2={row.y}
              strokeOpacity={row.o}
            />
          ))}
          <line x1={0} y1={yh} x2={W} y2={yh} strokeWidth={3 * u} />
        </g>
        {/* Haze that swallows the converging lines at the horizon. */}
        <rect
          y={yh - 6 * u}
          width={W}
          height={0.12 * H}
          fill={c.skyHorizon}
          opacity={0.5}
          filter={`url(#${id}-haze)`}
        />
      </svg>
    </AbsoluteFill>
  );
}

const elementSchema = {
  ...Interactive.baseSchema,
  gridSpeed: {
    type: "number",
    default: 2,
    min: 0,
    max: 6,
    step: 0.25,
    description: "Grid speed",
    hiddenFromList: false,
  },
  horizon: {
    type: "number",
    default: 0.6,
    min: 0.4,
    max: 0.8,
    step: 0.01,
    description: "Horizon",
    hiddenFromList: false,
  },
  sunStripes: {
    type: "boolean",
    default: true,
    description: "Scrolling sun stripes",
  },
  grid: {
    type: "color",
    default: "#E5322D",
    description: "Grid",
  },
  sunTop: {
    type: "color",
    default: "#FFC46B",
    description: "Sun top",
  },
  sunBottom: {
    type: "color",
    default: "#E5322D",
    description: "Sun bottom",
  },
  skyHorizon: {
    type: "color",
    default: "#3B0C10",
    description: "Horizon glow",
  },
  speed: {
    type: "number",
    default: 1,
    min: 0.25,
    max: 4,
    step: 0.25,
    description: "Speed",
    hiddenFromList: false,
  },
  ...Interactive.transformSchema,
} as const satisfies InteractivitySchema;

const ELEMENT_PROP_KEYS = new Set(["gridSpeed","horizon","sunStripes","grid","sunTop","sunBottom","skyHorizon","speed"]);

const ELEMENT_PROP_DEFAULTS: Record<string, unknown> = {
  gridSpeed: 2,
  horizon: 0.6,
  sunStripes: true,
  grid: "#E5322D",
  sunTop: "#FFC46B",
  sunBottom: "#E5322D",
  skyHorizon: "#3B0C10",
  speed: 1,
};

type SynthwaveElementProps = InteractiveBaseProps &
  InteractiveTransformProps &
  ComponentProps<typeof SynthwaveBase>;

const SynthwaveInner = forwardRef<
  HTMLDivElement,
  SynthwaveElementProps & { readonly controls: SequenceControls | undefined }
>(({ controls, name, style, ...rest }, ref) => {
  const outlineRef = useRef<HTMLDivElement>(null);
  useImperativeHandle(ref, () => outlineRef.current as HTMLDivElement, []);
  const componentProps: Record<string, unknown> = { ...ELEMENT_PROP_DEFAULTS };
  const sequenceProps: Record<string, unknown> = {};
  for (const [key, value] of Object.entries(rest)) {
    if (ELEMENT_PROP_KEYS.has(key)) {
      if (value !== undefined) componentProps[key] = value;
    } else {
      sequenceProps[key] = value;
    }
  }
  return (
    <Sequence
      layout="none"
      {...sequenceProps}
      controls={controls}
      name={name ?? "<Synthwave>"}
      outlineRef={outlineRef}
    >
      <div
        ref={outlineRef}
        style={{
          position: "relative",
          width: "100%",
          height: "100%",
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
          ...style,
        }}
      >
        <SynthwaveBase
          {...(componentProps as unknown as ComponentProps<typeof SynthwaveBase>)}
        />
      </div>
    </Sequence>
  );
});

export const Synthwave = Interactive.withSchema({
  Component: SynthwaveInner,
  componentName: "<Synthwave>",
  componentIdentity: null,
  schema: elementSchema,
  supportsEffects: false,
});
